from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def to_cents(value):
    if value is None or value == "":
        return 0
    try:
        amount = Decimal(str(value))
    except InvalidOperation:
        raise ValueError("Amount is not a number: " + str(value))
    return int((amount * 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))


def fmt(cents_value):
    sign = "-" if cents_value < 0 else ""
    whole, part = divmod(abs(cents_value), 100)
    return sign + str(whole) + "." + str(part).zfill(2)


invoice = params.get("invoice") or {}
payment = params.get("payment") or {}
limit_cents = to_cents(params.get("threshold"))
account_code = str(params.get("account_code") or "")
notes = []

expected_cents = to_cents(invoice.get("amountExpected"))
received_cents = to_cents(payment.get("amount"))
difference_cents = expected_cents - received_cents
difference = fmt(difference_cents)

currency_matches = (invoice.get("currency") or "") == (payment.get("currency") or "")
if not currency_matches:
    notes.append("The invoice and the payment are in different currencies; no adjustment is offered.")

balanced = difference_cents == 0 and currency_matches
is_short = difference_cents > 0
within_threshold = is_short and difference_cents <= limit_cents and currency_matches
if is_short and currency_matches and not within_threshold:
    notes.append("The shortfall is above the write-off threshold; an adjustment is not offered.")
if difference_cents < 0:
    notes.append("The payment is more than the invoice. Treat it as an overpayment, not a write-off.")

external_ref = "RECON-" + str(invoice.get("number") or "") + "-" + str(payment.get("reference") or "")
credit_note = {}
if within_threshold:
    if not account_code:
        notes.append("No write-off account code is set in Preferences, so an adjustment cannot be built.")
    else:
        credit_note = {
            "Type": "ACCRECCREDIT",
            "Contact": {"ContactID": invoice.get("contactId")},
            "Date": payment.get("date") or invoice.get("date"),
            "Status": "AUTHORISED",
            "Reference": external_ref,
            "CurrencyCode": invoice.get("currency"),
            "LineAmountTypes": "NoTax",
            "LineItems": [
                {
                    "Description": "Short payment adjustment for invoice " + str(invoice.get("number")) + " (payment " + str(payment.get("reference")) + ")",
                    "Quantity": 1,
                    "UnitAmount": float(Decimal(difference_cents) / 100),
                    "AccountCode": account_code,
                }
            ],
        }
